SUBROUTINE DROTMG (DD1,DD2,DX1,DY1,DPARAM)
!
!     CONSTRUCT THE MODIFIED GIVENS TRANSFORMATION MATRIX H WHICH ZEROS
!     THE SECOND COMPONENT OF THE 2-VECTOR  (DSQRT(DD1)*DX1,DSQRT(DD2)*
!     DY1)**T.
!     WITH DPARAM(1)=DFLAG, H HAS ONE OF THE FOLLOWING FORMS..
!
!     DFLAG=-1.D0     DFLAG=0.D0        DFLAG=1.D0     DFLAG=-2.D0
!
!       (DH11  DH12)    (1.D0  DH12)    (DH11  1.D0)    (1.D0  0.D0)
!     H=(          )    (          )    (          )    (          )
!       (DH21  DH22),   (DH21  1.D0),   (-1.D0 DH22),   (0.D0  1.D0).
!
!     LOCATIONS 2-4 OF DPARAM CONTAIN DH11,DH21,DH12, AND DH22
!     RESPECTIVELY. (VALUES OF 1.D0, -1.D0, OR 0.D0 IMPLIED BY THE
!     VALUE OF DPARAM(1) ARE NOT STORED IN DPARAM.)
!
!     IT IS ASSUMED THAT GAMSQ = GAM*GAM AND RGAMSQ = ONE/(GAM*GAM).
!     THE VALUES OF GAMSQ AND RGAMSQ SET IN THE DATA STATEMENT MAY BE
!     INEXACT.  THIS IS OK AS THEY ARE ONLY USED FOR TESTING THE SIZE
!     OF DD1 AND DD2.  ALL ACTUAL SCALING OF DATA IS DONE USING GAM.
!
DOUBLE PRECISION GAM,ONE,RGAMSQ,DD2,DH11,DH21,DPARAM,DP2, &
&DQ2,DU,DY1,ZERO,GAMSQ,DD1,DFLAG,DH12,DH22,DP1,DQ1, &
&DTEMP,DX1,TWO
DIMENSION DPARAM(5)
!
DATA ZERO,ONE,TWO /0.D0,1.D0,2.D0/
DATA GAM,GAMSQ,RGAMSQ/4096.D0,16777216.D0,5.9604645D-8/
!
IF (DD1 .LT. ZERO) GO TO 60
DP2 = DD2*DY1
IF (DP2 .NE. ZERO) GO TO 20
    DFLAG = -TWO
    GO TO 260
!
!     REGULAR-CASE..
!
20 DP1 = DD1*DX1
DQ1 = DP1*DX1
DQ2 = DP2*DY1
!
IF (DABS(DQ1) .LE. DABS(DQ2)) GO TO 40
    DH21 = -DY1/DX1
    DH12 = DP2/DP1
!
    DU = ONE - DH12*DH21
    IF (DU .LE. ZERO) GO TO 60
!
         DFLAG = ZERO
         DH11 = ONE
         DH22 = ONE
         DD1 = DD1/DU
         DD2 = DD2/DU
         DX1 = DX1*DU
!         GO SCALE-CHECK..
         GO TO 100
!
40 CONTINUE
    IF (DD2 .LT. ZERO) GO TO 60
         DFLAG = ONE
         DH11 = DP1/DP2
         DH21 = -ONE
         DH12 = ONE
         DH22 = DX1/DY1
!
         DU = ONE + DH11*DH22
         DTEMP = DD2/DU
         DD2 = DD1/DU
         DD1 = DTEMP
         DX1 = DY1*DU
!         GO SCALE-CHECK
         GO TO 100
!
!     PROCEDURE..ZERO-H-D-AND-DX1..
!
60 CONTINUE
    DFLAG = -ONE
    DH11 = ZERO
    DH12 = ZERO
    DH21 = ZERO
    DH22 = ZERO
!
    DD1 = ZERO
    DD2 = ZERO
    DX1 = ZERO
    GO TO 250
!
!     PROCEDURE..SCALE-CHECK
!
100 CONTINUE
110 CONTINUE
    IF (DD1 .GT. RGAMSQ) GO TO 130
         IF (DD1 .EQ. ZERO) GO TO 160
         DFLAG = -ONE
         DD1 = DD1*(GAM*GAM)
         DX1 = DX1/GAM
         DH11 = DH11/GAM
         DH12 = DH12/GAM
    GO TO 110
!
130 CONTINUE
140 CONTINUE
    IF (DD1 .LT. GAMSQ) GO TO 160
         DFLAG = -ONE
         DD1 = DD1/(GAM*GAM)
         DX1 = DX1*GAM
         DH11 = DH11*GAM
         DH12 = DH12*GAM
    GO TO 140
!
160 CONTINUE
170 CONTINUE
    IF (DABS(DD2) .GT. RGAMSQ) GO TO 190
         IF (DD2 .EQ. ZERO) GO TO 220
         DFLAG = -ONE
         DD2 = DD2*(GAM*GAM)
         DH21 = DH21/GAM
         DH22 = DH22/GAM
    GO TO 170
!
190 CONTINUE
200 CONTINUE
    IF (DABS(DD2) .LT. GAMSQ) GO TO 220
         DFLAG = -ONE
         DD2 = DD2/(GAM*GAM)
         DH21 = DH21*GAM
         DH22 = DH22*GAM
    GO TO 200
!
220 CONTINUE
    IF(DFLAG)250,230,240
230 CONTINUE
         DPARAM(3)=DH21
         DPARAM(4)=DH12
         GO TO 260
240 CONTINUE
         DPARAM(2)=DH11
         DPARAM(5)=DH22
         GO TO 260
250 CONTINUE
         DPARAM(2)=DH11
         DPARAM(3)=DH21
         DPARAM(4)=DH12
         DPARAM(5)=DH22
260 CONTINUE
    DPARAM(1)=DFLAG
    RETURN
END SUBROUTINE DROTMG

SUBROUTINE DROTM (N,DX,INCX,DY,INCY,DPARAM)
!
!     APPLY THE MODIFIED GIVENS TRANSFORMATION, H, TO THE 2 BY N MATRIX
!
!     (DX**T), WHERE **T INDICATES TRANSPOSE. THE ELEMENTS OF DX ARE IN
!     (DY**T)
!
!     DX(LX+I*INCX), I = 0 TO N-1, WHERE LX = 1 IF INCX .GE. 0, ELSE
!     LX = (-INCX)*N, AND SIMILARLY FOR SY USING LY AND INCY.
!
!     WITH DPARAM(1)=DFLAG, H HAS ONE OF THE FOLLOWING FORMS..
!
!     DFLAG=-1.D0     DFLAG=0.D0        DFLAG=1.D0     DFLAG=-2.D0
!
!       (DH11  DH12)    (1.D0  DH12)    (DH11  1.D0)    (1.D0  0.D0)
!     H=(          )    (          )    (          )    (          )
!       (DH21  DH22),   (DH21  1.D0),   (-1.D0 DH22),   (0.D0  1.D0).
!
DOUBLE PRECISION DFLAG,DH12,DH22,DX,TWO,Z,DH11,DH21, &
&DPARAM,DY,W,ZERO
DIMENSION DX(*), DY(*), DPARAM(5)
!
DATA ZERO,TWO/0.D0,2.D0/
!
DFLAG=DPARAM(1)
IF(N .LE. 0 .OR.(DFLAG+TWO.EQ.ZERO)) GO TO 140
    IF(.NOT.(INCX.EQ.INCY.AND. INCX .GT.0)) GO TO 70
!
         NSTEPS=N*INCX
         IF(DFLAG) 50,10,30
10 CONTINUE
         DH21=DPARAM(3)
         DH12=DPARAM(4)
              DO I=1,NSTEPS,INCX
              W=DX(I)
              Z=DY(I)
              DX(I)=W+Z*DH12
              DY(I)=W*DH21+Z
              END DO
         GO TO 140
30 CONTINUE
         DH11=DPARAM(2)
         DH22=DPARAM(5)
              DO I=1,NSTEPS,INCX
              W=DX(I)
              Z=DY(I)
              DX(I)=W*DH11+Z
              DY(I)=-W+DH22*Z
              END DO
         GO TO 140
50 CONTINUE
         DH11=DPARAM(2)
         DH21=DPARAM(3)
         DH12=DPARAM(4)
         DH22=DPARAM(5)
              DO I=1,NSTEPS,INCX
              W=DX(I)
              Z=DY(I)
              DX(I)=W*DH11+Z*DH12
              DY(I)=W*DH21+Z*DH22
              END DO
         GO TO 140
70 CONTINUE
    KX=1
    KY=1
    IF(INCX .LT. 0) KX=1+(1-N)*INCX
    IF(INCY .LT. 0) KY=1+(1-N)*INCY
!
    IF(DFLAG)120,80,100
80 CONTINUE
    DH21=DPARAM(3)
    DH12=DPARAM(4)
         DO I=1,N
         W=DX(KX)
         Z=DY(KY)
         DX(KX)=W+Z*DH12
         DY(KY)=W*DH21+Z
         KX=KX+INCX
         KY=KY+INCY
         END DO
    GO TO 140
100 CONTINUE
    DH11=DPARAM(2)
    DH22=DPARAM(5)
         DO I=1,N
         W=DX(KX)
         Z=DY(KY)
         DX(KX)=W*DH11+Z
         DY(KY)=-W+DH22*Z
         KX=KX+INCX
         KY=KY+INCY
         END DO
    GO TO 140
120 CONTINUE
    DH11=DPARAM(2)
    DH21=DPARAM(3)
    DH12=DPARAM(4)
    DH22=DPARAM(5)
         DO I=1,N
         W=DX(KX)
         Z=DY(KY)
         DX(KX)=W*DH11+Z*DH12
         DY(KY)=W*DH21+Z*DH22
         KX=KX+INCX
         KY=KY+INCY
         END DO
140 CONTINUE
    RETURN
    END SUBROUTINE DROTM

REAL function SDOT(N,SX,INCX,SY,INCY)
IMPLICIT NONE
!
!     FORMS THE DOT PRODUCT OF TWO VECTORS.
!     USES UNROLLED LOOPS FOR INCREMENTS EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL SX(*),SY(*),STEMP
INTEGER I,INCX,INCY,IX,IY,M,MP1,N
!
STEMP = 0.0E0
SDOT = 0.0E0
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  STEMP = STEMP + SX(IX)*SY(IY)
  IX = IX + INCX
  IY = IY + INCY
END DO
SDOT = STEMP
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,5)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  STEMP = STEMP + SX(I)*SY(I)
END DO
IF( N .LT. 5 ) GO TO 60
40 MP1 = M + 1
DO I = MP1,N,5
  STEMP = STEMP + SX(I)*SY(I) + SX(I + 1)*SY(I + 1) + &
&SX(I + 2)*SY(I + 2) + SX(I + 3)*SY(I + 3) + SX(I + 4)*SY(I + 4)
END DO
60 SDOT = STEMP
RETURN
END FUNCTION SDOT

double precision function DDOT(N,DX,INCX,DY,INCY)
IMPLICIT NONE
!
!     FORMS THE DOT PRODUCT OF TWO VECTORS.
!     USES UNROLLED LOOPS FOR INCREMENTS EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION DX(*),DY(*),DTEMP
INTEGER I,INCX,INCY,IX,IY,M,MP1,N
!
DDOT = 0.0D0
DTEMP = 0.0D0
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  DTEMP = DTEMP + DX(IX)*DY(IY)
  IX = IX + INCX
  IY = IY + INCY
END DO
DDOT = DTEMP
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,5)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  DTEMP = DTEMP + DX(I)*DY(I)
END DO
IF( N .LT. 5 ) GO TO 60
40 MP1 = M + 1
DO I = MP1,N,5
  DTEMP = DTEMP + DX(I)*DY(I) + DX(I + 1)*DY(I + 1) + &
&DX(I + 2)*DY(I + 2) + DX(I + 3)*DY(I + 3) + DX(I + 4)*DY(I + 4)
END DO
60 DDOT = DTEMP
RETURN
END FUNCTION DDOT

COMPLEX function CDOTC(N,CX,INCX,CY,INCY)
IMPLICIT NONE
!
!     FORMS THE DOT PRODUCT OF TWO VECTORS, CONJUGATING THE FIRST
!     VECTOR.
!     JACK DONGARRA, LINPACK,  3/11/78.
!
COMPLEX CX(*),CY(*),CTEMP
INTEGER I,INCX,INCY,IX,IY,N
!
CTEMP = (0.0,0.0)
CDOTC = (0.0,0.0)
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  CTEMP = CTEMP + CONJG(CX(IX))*CY(IY)
  IX = IX + INCX
  IY = IY + INCY
END DO
CDOTC = CTEMP
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
20 DO I = 1,N
  CTEMP = CTEMP + CONJG(CX(I))*CY(I)
END DO
CDOTC = CTEMP
RETURN
END FUNCTION CDOTC

COMPLEX function CDOTU(N,CX,INCX,CY,INCY)
!
!     FORMS THE DOT PRODUCT OF TWO VECTORS.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX CX(*),CY(*),CTEMP
INTEGER I,INCX,INCY,IX,IY,N
!
CTEMP = (0.0,0.0)
CDOTU = (0.0,0.0)
IF(N.LE.0)RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  CTEMP = CTEMP + CX(IX)*CY(IY)
  IX = IX + INCX
  IY = IY + INCY
END DO
CDOTU = CTEMP
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
20 DO I = 1,N
  CTEMP = CTEMP + CX(I)*CY(I)
END DO
CDOTU = CTEMP
RETURN
END FUNCTION CDOTU

SUBROUTINE  SSCAL(N,SA,SX,INCX)
IMPLICIT NONE
!
!     SCALES A VECTOR BY A CONSTANT.
!     USES UNROLLED LOOPS FOR INCREMENT EQUAL TO 1.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL SA,SX(*)
INTEGER I,INCX,M,MP1,N,NINCX
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  SX(I) = SA*SX(I)
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,5)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  SX(I) = SA*SX(I)
END DO
IF( N .LT. 5 ) RETURN
40 MP1 = M + 1
DO I = MP1,N,5
  SX(I) = SA*SX(I)
  SX(I + 1) = SA*SX(I + 1)
  SX(I + 2) = SA*SX(I + 2)
  SX(I + 3) = SA*SX(I + 3)
  SX(I + 4) = SA*SX(I + 4)
END DO
RETURN
END SUBROUTINE SSCAL

SUBROUTINE  DSCAL(N,DA,DX,INCX)
IMPLICIT NONE
!
!     SCALES A VECTOR BY A CONSTANT.
!     USES UNROLLED LOOPS FOR INCREMENT EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION DA,DX(*)
INTEGER I,INCX,M,MP1,N,NINCX
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  DX(I) = DA*DX(I)
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,5)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  DX(I) = DA*DX(I)
END DO
IF( N .LT. 5 ) RETURN
40 MP1 = M + 1
DO I = MP1,N,5
  DX(I) = DA*DX(I)
  DX(I + 1) = DA*DX(I + 1)
  DX(I + 2) = DA*DX(I + 2)
  DX(I + 3) = DA*DX(I + 3)
  DX(I + 4) = DA*DX(I + 4)
END DO
RETURN
END SUBROUTINE DSCAL

SUBROUTINE  CSCAL(N,CA,CX,INCX)
IMPLICIT NONE
!
!     SCALES A VECTOR BY A CONSTANT.
!     JACK DONGARRA, LINPACK,  3/11/78.
!
COMPLEX CA,CX(*)
INTEGER I,INCX,N,NINCX
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  CX(I) = CA*CX(I)
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 DO I = 1,N
  CX(I) = CA*CX(I)
END DO
RETURN
END SUBROUTINE CSCAL

SUBROUTINE  CSSCAL(N,SA,CX,INCX)
IMPLICIT NONE
!
!     SCALES A COMPLEX VECTOR BY A REAL CONSTANT.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX CX(*)
REAL SA
INTEGER I,INCX,N,NINCX
!
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  CX(I) = CMPLX(SA*REAL(CX(I)),SA*AIMAG(CX(I)))
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 DO I = 1,N
  CX(I) = CMPLX(SA*REAL(CX(I)),SA*AIMAG(CX(I)))
END DO
RETURN
END SUBROUTINE CSSCAL

SUBROUTINE SAXPY(N,SA,SX,INCX,SY,INCY)
IMPLICIT NONE
!
!     CONSTANT TIMES A VECTOR PLUS A VECTOR.
!     USES UNROLLED LOOP FOR INCREMENTS EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL SX(*),SY(*),SA
INTEGER I,INCX,INCY,IX,IY,M,MP1,N
!
IF(N.LE.0)RETURN
IF (SA .EQ. 0.0) RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  SY(IY) = SY(IY) + SA*SX(IX)
  IX = IX + INCX
  IY = IY + INCY
END DO
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,4)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  SY(I) = SY(I) + SA*SX(I)
END DO
IF( N .LT. 4 ) RETURN
40 MP1 = M + 1
DO I = MP1,N,4
  SY(I) = SY(I) + SA*SX(I)
  SY(I + 1) = SY(I + 1) + SA*SX(I + 1)
  SY(I + 2) = SY(I + 2) + SA*SX(I + 2)
  SY(I + 3) = SY(I + 3) + SA*SX(I + 3)
END DO
RETURN
END SUBROUTINE SAXPY

SUBROUTINE DAXPY(N,DA,DX,INCX,DY,INCY)
IMPLICIT NONE
!
!     CONSTANT TIMES A VECTOR PLUS A VECTOR.
!     USES UNROLLED LOOPS FOR INCREMENTS EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION DX(*),DY(*),DA
INTEGER I,INCX,INCY,IX,IY,M,MP1,N
!
IF(N.LE.0)RETURN
IF (DA .EQ. 0.0D0) RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  DY(IY) = DY(IY) + DA*DX(IX)
  IX = IX + INCX
  IY = IY + INCY
END DO
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,4)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  DY(I) = DY(I) + DA*DX(I)
END DO
IF( N .LT. 4 ) RETURN
40 MP1 = M + 1
DO I = MP1,N,4
  DY(I) = DY(I) + DA*DX(I)
  DY(I + 1) = DY(I + 1) + DA*DX(I + 1)
  DY(I + 2) = DY(I + 2) + DA*DX(I + 2)
  DY(I + 3) = DY(I + 3) + DA*DX(I + 3)
END DO
RETURN
END SUBROUTINE DAXPY

SUBROUTINE CAXPY(N,CA,CX,INCX,CY,INCY)
IMPLICIT NONE
!
!     CONSTANT TIMES A VECTOR PLUS A VECTOR.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX CX(*),CY(*),CA
INTEGER I,INCX,INCY,IX,IY,N
!
IF(N.LE.0)RETURN
IF (ABS(REAL(CA)) + ABS(AIMAG(CA)) .EQ. 0.0 ) RETURN
IF(INCX.EQ.1.AND.INCY.EQ.1)GO TO 20
!
!        CODE FOR UNEQUAL INCREMENTS OR EQUAL INCREMENTS
!          NOT EQUAL TO 1
!
IX = 1
IY = 1
IF(INCX.LT.0)IX = (-N+1)*INCX + 1
IF(INCY.LT.0)IY = (-N+1)*INCY + 1
DO I = 1,N
  CY(IY) = CY(IY) + CA*CX(IX)
  IX = IX + INCX
  IY = IY + INCY
END DO
RETURN
!
!        CODE FOR BOTH INCREMENTS EQUAL TO 1
!
20 DO I = 1,N
  CY(I) = CY(I) + CA*CX(I)
END DO
RETURN
END SUBROUTINE CAXPY

REAL function SASUM(N,SX,INCX)
IMPLICIT NONE
!
!     TAKES THE SUM OF THE ABSOLUTE VALUES.
!     USES UNROLLED LOOPS FOR INCREMENT EQUAL TO ONE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL SX(*),STEMP
INTEGER I,INCX,M,MP1,N,NINCX
!
SASUM = 0.0E0
STEMP = 0.0E0
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  STEMP = STEMP + ABS(SX(I))
END DO
SASUM = STEMP
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,6)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  STEMP = STEMP + ABS(SX(I))
END DO
IF( N .LT. 6 ) GO TO 60
40 MP1 = M + 1
DO I = MP1,N,6
  STEMP = STEMP + ABS(SX(I)) + ABS(SX(I + 1)) + ABS(SX(I + 2)) &
&+ ABS(SX(I + 3)) + ABS(SX(I + 4)) + ABS(SX(I + 5))
END DO
60 SASUM = STEMP
RETURN
END FUNCTION SASUM

double precision function DASUM(N,DX,INCX)
IMPLICIT NONE
!
!     TAKES THE SUM OF THE ABSOLUTE VALUES.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION DX(*),DTEMP
INTEGER I,INCX,M,MP1,N,NINCX
!
DASUM = 0.0D0
DTEMP = 0.0D0
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  DTEMP = DTEMP + DABS(DX(I))
END DO
DASUM = DTEMP
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
!
!        CLEAN-UP LOOP
!
20 M = MOD(N,6)
IF( M .EQ. 0 ) GO TO 40
DO I = 1,M
  DTEMP = DTEMP + DABS(DX(I))
END DO
IF( N .LT. 6 ) GO TO 60
40 MP1 = M + 1
DO I = MP1,N,6
  DTEMP = DTEMP + DABS(DX(I)) + DABS(DX(I + 1)) + DABS(DX(I + 2)) &
&+ DABS(DX(I + 3)) + DABS(DX(I + 4)) + DABS(DX(I + 5))
END DO
60 DASUM = DTEMP
RETURN
END FUNCTION DASUM

REAL function SCASUM(N,CX,INCX)
IMPLICIT NONE
!
!     TAKES THE SUM OF THE ABSOLUTE VALUES OF A COMPLEX VECTOR AND
!     RETURNS A SINGLE PRECISION RESULT.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX CX(*)
REAL STEMP
INTEGER I,INCX,N,NINCX
!
SCASUM = 0.0E0
STEMP = 0.0E0
IF(N.LE.0)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
NINCX = N*INCX
DO I = 1,NINCX,INCX
  STEMP = STEMP + ABS(REAL(CX(I))) + ABS(AIMAG(CX(I)))
END DO
SCASUM = STEMP
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 DO I = 1,N
  STEMP = STEMP + ABS(REAL(CX(I))) + ABS(AIMAG(CX(I)))
END DO
SCASUM = STEMP
RETURN
END FUNCTION SCASUM

REAL function SNRM2 ( N, SX, INCX)
IMPLICIT NONE
INTEGER INCX, N
INTEGER I, J, NN
INTEGER NEXT
REAL SX(*),  CUTLO, CUTHI, HITEST, SUM, XMAX, ZERO, ONE
DATA   ZERO, ONE /0.0E0, 1.0E0/
!
!     EUCLIDEAN NORM OF THE N-VECTOR STORED IN SX() WITH STORAGE
!     INCREMENT INCX .
!     IF    N .LE. 0 RETURN WITH RESULT = 0.
!     IF N .GE. 1 THEN INCX MUST BE .GE. 1
!
!           C.L.LAWSON, 1978 JAN 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     HOPEFULLY APPLICABLE TO ALL MACHINES.
!         CUTLO = MAXIMUM OF  SQRT(U/EPS)  OVER ALL KNOWN MACHINES.
!         CUTHI = MINIMUM OF  SQRT(V)      OVER ALL KNOWN MACHINES.
!     WHERE
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     BRIEF OUTLINE OF ALGORITHM..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. CUTLO
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. CUTLO
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. CUTHI/M
!     WHERE M = N FOR X() REAL AND M = 2*N FOR COMPLEX.
!
!     VALUES FOR CUTLO AND CUTHI..
!     FROM THE ENVIRONMENTAL PARAMETERS LISTED IN THE IMSL CONVERTER
!     DOCUMENT THE LIMITING VALUES ARE AS FOLLOWS..
!     CUTLO, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS CUTLO = 2**(-51) = 4.44089E-16
!     CUTHI, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS CUTHI = 2**(63.5) = 1.30438E19
!     CUTLO, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS CUTLO = 2**(-33.5) = 8.23181D-11
!     CUTHI, D.P.   SAME AS S.P.  CUTHI = 1.30438D19
!     DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!     DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
!
IF(N .GT. 0) GO TO 10
   SNRM2  = ZERO
   GO TO 300
!
10 assign 30 to NEXT
SUM = ZERO
NN = N * INCX
!                                                 BEGIN MAIN LOOP
I = 1
20 GO TO NEXT,(30, 50, 70, 110)
30 IF( ABS(SX(I)) .GT. CUTLO) GO TO 85
assign 50 to NEXT
XMAX = ZERO
!
!                        PHASE 1.  SUM IS ZERO
!
50 IF( SX(I) .EQ. ZERO) GO TO 200
IF( ABS(SX(I)) .GT. CUTLO) GO TO 85
!
!                                PREPARE FOR PHASE 2.
assign 70 to NEXT
GO TO 105
!
!                                PREPARE FOR PHASE 4.
!
100 I = J
assign 110 to NEXT
SUM = (SUM / SX(I)) / SX(I)
105 XMAX = ABS(SX(I))
GO TO 115
!
!                   PHASE 2.  SUM IS SMALL.
!                             SCALE TO AVOID DESTRUCTIVE UNDERFLOW.
!
70 IF( ABS(SX(I)) .GT. CUTLO ) GO TO 75
!
!                     COMMON CODE FOR PHASES 2 AND 4.
!                     IN PHASE 4 SUM IS LARGE.  SCALE TO AVOID OVERFLOW.
!
110 IF( ABS(SX(I)) .LE. XMAX ) GO TO 115
   SUM = ONE + SUM * (XMAX / SX(I))**2
   XMAX = ABS(SX(I))
   GO TO 200
!
115 SUM = SUM + (SX(I)/XMAX)**2
GO TO 200
!
!
!                  PREPARE FOR PHASE 3.
!
75 SUM = (SUM * XMAX) * XMAX
!
!
!     FOR REAL OR D.P. SET HITEST = CUTHI/N
!     FOR COMPLEX      SET HITEST = CUTHI/(2*N)
!
85 HITEST = CUTHI/FLOAT( N )
!
!                   PHASE 3.  SUM IS MID-RANGE.  NO SCALING.
!
do 95 J = I,NN,INCX
IF(ABS(SX(J)) .GE. HITEST) GO TO 100
95 SUM = SUM + SX(J)**2
SNRM2 = SQRT( SUM )
GO TO 300
!
200 CONTINUE
I = I + INCX
IF ( I .LE. NN ) GO TO 20
!
!              END OF MAIN LOOP.
!
!              COMPUTE SQUARE ROOT AND ADJUST FOR SCALING.
!
SNRM2 = XMAX * SQRT(SUM)
300 CONTINUE
RETURN
END FUNCTION SNRM2

double precision function DNRM2 ( N, DX, INCX)
IMPLICIT NONE
INTEGER INCX, N
INTEGER I, J, NN
INTEGER NEXT
DOUBLE PRECISION DX(*), CUTLO, CUTHI, HITEST, SUM, XMAX,ZERO,ONE
DATA   ZERO, ONE /0.0D0, 1.0D0/
!
!     EUCLIDEAN NORM OF THE N-VECTOR STORED IN DX() WITH STORAGE
!     INCREMENT INCX .
!     IF    N .LE. 0 RETURN WITH RESULT = 0.
!     IF N .GE. 1 THEN INCX MUST BE .GE. 1
!
!           C.L.LAWSON, 1978 JAN 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     HOPEFULLY APPLICABLE TO ALL MACHINES.
!         CUTLO = MAXIMUM OF  DSQRT(U/EPS)  OVER ALL KNOWN MACHINES.
!         CUTHI = MINIMUM OF  DSQRT(V)      OVER ALL KNOWN MACHINES.
!     WHERE
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     BRIEF OUTLINE OF ALGORITHM..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. CUTLO
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. CUTLO
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. CUTHI/M
!     WHERE M = N FOR X() REAL AND M = 2*N FOR COMPLEX.
!
!     VALUES FOR CUTLO AND CUTHI..
!     FROM THE ENVIRONMENTAL PARAMETERS LISTED IN THE IMSL CONVERTER
!     DOCUMENT THE LIMITING VALUES ARE AS FOLLOWS..
!     CUTLO, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS CUTLO = 2**(-51) = 4.44089E-16
!     CUTHI, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS CUTHI = 2**(63.5) = 1.30438E19
!     CUTLO, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS CUTLO = 2**(-33.5) = 8.23181D-11
!     CUTHI, D.P.   SAME AS S.P.  CUTHI = 1.30438D19
!     DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!     DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!
IF(N .GT. 0) GO TO 10
   DNRM2  = ZERO
   GO TO 300
!
10 assign 30 to NEXT
SUM = ZERO
NN = N * INCX
!                                                 BEGIN MAIN LOOP
I = 1
20 GO TO NEXT,(30, 50, 70, 110)
30 IF( DABS(DX(I)) .GT. CUTLO) GO TO 85
assign 50 to NEXT
XMAX = ZERO
!
!                        PHASE 1.  SUM IS ZERO
!
50 IF( DX(I) .EQ. ZERO) GO TO 200
IF( DABS(DX(I)) .GT. CUTLO) GO TO 85
!
!                                PREPARE FOR PHASE 2.
assign 70 to NEXT
GO TO 105
!
!                                PREPARE FOR PHASE 4.
!
100 I = J
assign 110 to NEXT
SUM = (SUM / DX(I)) / DX(I)
105 XMAX = DABS(DX(I))
GO TO 115
!
!                   PHASE 2.  SUM IS SMALL.
!                             SCALE TO AVOID DESTRUCTIVE UNDERFLOW.
!
70 IF( DABS(DX(I)) .GT. CUTLO ) GO TO 75
!
!                     COMMON CODE FOR PHASES 2 AND 4.
!                     IN PHASE 4 SUM IS LARGE.  SCALE TO AVOID OVERFLOW.
!
110 IF( DABS(DX(I)) .LE. XMAX ) GO TO 115
   SUM = ONE + SUM * (XMAX / DX(I))**2
   XMAX = DABS(DX(I))
   GO TO 200
!
115 SUM = SUM + (DX(I)/XMAX)**2
GO TO 200
!
!
!                  PREPARE FOR PHASE 3.
!
75 SUM = (SUM * XMAX) * XMAX
!
!
!     FOR REAL OR D.P. SET HITEST = CUTHI/N
!     FOR COMPLEX      SET HITEST = CUTHI/(2*N)
!
85 HITEST = CUTHI/FLOAT( N )
!
!                   PHASE 3.  SUM IS MID-RANGE.  NO SCALING.
!
do 95 J = I,NN,INCX
IF(DABS(DX(J)) .GE. HITEST) GO TO 100
95 SUM = SUM + DX(J)**2
DNRM2 = DSQRT( SUM )
GO TO 300
!
200 CONTINUE
I = I + INCX
IF ( I .LE. NN ) GO TO 20
!
!              END OF MAIN LOOP.
!
!              COMPUTE SQUARE ROOT AND ADJUST FOR SCALING.
!
DNRM2 = XMAX * DSQRT(SUM)
300 CONTINUE
RETURN
END FUNCTION DNRM2

REAL function SCNRM2( N, CX, INCX)
IMPLICIT NONE
INTEGER INCX, N
INTEGER I, NN
LOGICAL IMAG, SCALE
INTEGER NEXT
REAL CUTLO, CUTHI, HITEST, SUM, XMAX, ABSX, ZERO, ONE
COMPLEX CX(*)
DATA         ZERO, ONE /0.0E0, 1.0E0/
!
!     UNITARY NORM OF THE COMPLEX N-VECTOR STORED IN CX() WITH STORAGE
!     INCREMENT INCX .
!     IF    N .LE. 0 RETURN WITH RESULT = 0.
!     IF N .GE. 1 THEN INCX MUST BE .GE. 1
!
!           C.L.LAWSON , 1978 JAN 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     HOPEFULLY APPLICABLE TO ALL MACHINES.
!         CUTLO = MAXIMUM OF  SQRT(U/EPS)  OVER ALL KNOWN MACHINES.
!         CUTHI = MINIMUM OF  SQRT(V)      OVER ALL KNOWN MACHINES.
!     WHERE
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     BRIEF OUTLINE OF ALGORITHM..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. CUTLO
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. CUTLO
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. CUTHI/M
!     WHERE M = N FOR X() REAL AND M = 2*N FOR COMPLEX.
!
!     VALUES FOR CUTLO AND CUTHI..
!     FROM THE ENVIRONMENTAL PARAMETERS LISTED IN THE IMSL CONVERTER
!     DOCUMENT THE LIMITING VALUES ARE AS FOLLOWS..
!     CUTLO, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS CUTLO = 2**(-51) = 4.44089E-16
!     CUTHI, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS CUTHI = 2**(63.5) = 1.30438E19
!     CUTLO, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS CUTLO = 2**(-33.5) = 8.23181D-11
!     CUTHI, D.P.   SAME AS S.P.  CUTHI = 1.30438D19
!     DATA CUTLO, CUTHI / 8.232D-11,  1.304D19 /
!     DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
DATA CUTLO, CUTHI / 4.441E-16,  1.304E19 /
!
IF(N .GT. 0) GO TO 10
   SCNRM2  = ZERO
   GO TO 300
!
10 assign 30 to NEXT
SUM = ZERO
NN = N * INCX
!                                                 BEGIN MAIN LOOP
do 210 I = 1,NN,INCX
   ABSX = ABS(REAL(CX(I)))
   IMAG = .FALSE.
   GO TO NEXT,(30, 50, 70, 90, 110)
30 IF( ABSX .GT. CUTLO) GO TO 85
assign 50 to NEXT
SCALE = .FALSE.
!
!                        PHASE 1.  SUM IS ZERO
!
50 IF( ABSX .EQ. ZERO) GO TO 200
IF( ABSX .GT. CUTLO) GO TO 85
!
!                                PREPARE FOR PHASE 2.
assign 70 to NEXT
GO TO 105
!
!                                PREPARE FOR PHASE 4.
!
100 assign 110 to NEXT
SUM = (SUM / ABSX) / ABSX
105 SCALE = .TRUE.
XMAX = ABSX
GO TO 115
!
!                   PHASE 2.  SUM IS SMALL.
!                             SCALE TO AVOID DESTRUCTIVE UNDERFLOW.
!
70 IF( ABSX .GT. CUTLO ) GO TO 75
!
!                     COMMON CODE FOR PHASES 2 AND 4.
!                     IN PHASE 4 SUM IS LARGE.  SCALE TO AVOID OVERFLOW.
!
110 IF( ABSX .LE. XMAX ) GO TO 115
   SUM = ONE + SUM * (XMAX / ABSX)**2
   XMAX = ABSX
   GO TO 200
!
115 SUM = SUM + (ABSX/XMAX)**2
GO TO 200
!
!
!                  PREPARE FOR PHASE 3.
!
75 SUM = (SUM * XMAX) * XMAX
!
85 assign 90 to NEXT
SCALE = .FALSE.
!
!     FOR REAL OR D.P. SET HITEST = CUTHI/N
!     FOR COMPLEX      SET HITEST = CUTHI/(2*N)
!
HITEST = CUTHI/FLOAT( N )
HITEST = HITEST * 0.5
!
!                   PHASE 3.  SUM IS MID-RANGE.  NO SCALING.
!
90 IF(ABSX .GE. HITEST) GO TO 100
   SUM = SUM + ABSX**2
200 CONTINUE
!                  CONTROL SELECTION OF REAL AND IMAGINARY PARTS.
!
IF(IMAG) GO TO 210
   ABSX = ABS(AIMAG(CX(I)))
   IMAG = .TRUE.
GO TO NEXT,(  50, 70, 90, 110 )
!
210 CONTINUE
!
!              END OF MAIN LOOP.
!              COMPUTE SQUARE ROOT AND ADJUST FOR SCALING.
!
SCNRM2 = SQRT(SUM)
IF(SCALE) SCNRM2 = SCNRM2 * XMAX
300 CONTINUE
RETURN
END FUNCTION SCNRM2

INTEGER function ISAMAX(N,SX,INCX)
IMPLICIT NONE
!
!     FINDS THE INDEX OF ELEMENT HAVING MAX. ABSOLUTE VALUE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
REAL SX(*),SMAX
INTEGER I,INCX,IX,N
!
ISAMAX = 0
IF( N .LT. 1 ) RETURN
ISAMAX = 1
IF(N.EQ.1)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
IX = 1
SMAX = ABS(SX(1))
IX = IX + INCX
DO I = 2,N
   IF(ABS(SX(IX)).LE.SMAX) GO TO 5
   ISAMAX = I
   SMAX = ABS(SX(IX))
5 IX = IX + INCX
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 SMAX = ABS(SX(1))
do 30 I = 2,N
   IF(ABS(SX(I)).LE.SMAX) GO TO 30
   ISAMAX = I
   SMAX = ABS(SX(I))
30 CONTINUE
RETURN
END FUNCTION ISAMAX

INTEGER function IDAMAX(N,DX,INCX)
IMPLICIT NONE
!
!     FINDS THE INDEX OF ELEMENT HAVING MAX. ABSOLUTE VALUE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
DOUBLE PRECISION DX(*),DMAX
INTEGER I,INCX,IX,N
!
IDAMAX = 0
IF( N .LT. 1 ) RETURN
IDAMAX = 1
IF(N.EQ.1)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
IX = 1
DMAX = DABS(DX(1))
IX = IX + INCX
DO I = 2,N
   IF(DABS(DX(IX)).LE.DMAX) GO TO 5
   IDAMAX = I
   DMAX = DABS(DX(IX))
5 IX = IX + INCX
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 DMAX = DABS(DX(1))
do 30 I = 2,N
   IF(DABS(DX(I)).LE.DMAX) GO TO 30
   IDAMAX = I
   DMAX = DABS(DX(I))
30 CONTINUE
RETURN
END FUNCTION IDAMAX

INTEGER function ICAMAX(N,CX,INCX)
IMPLICIT NONE
!
!     FINDS THE INDEX OF ELEMENT HAVING MAX. ABSOLUTE VALUE.
!     JACK DONGARRA, LINPACK, 3/11/78.
!
COMPLEX CX(*)
REAL SMAX
INTEGER I,INCX,IX,N
COMPLEX ZDUM
REAL CABS1
CABS1(ZDUM) = ABS(REAL(ZDUM)) + ABS(AIMAG(ZDUM))
!
ICAMAX = 0
IF( N .LT. 1 ) RETURN
ICAMAX = 1
IF(N.EQ.1)RETURN
IF(INCX.EQ.1)GO TO 20
!
!        CODE FOR INCREMENT NOT EQUAL TO 1
!
IX = 1
SMAX = CABS1(CX(1))
IX = IX + INCX
DO I = 2,N
   IF(CABS1(CX(IX)).LE.SMAX) GO TO 5
   ICAMAX = I
   SMAX = CABS1(CX(IX))
5 IX = IX + INCX
END DO
RETURN
!
!        CODE FOR INCREMENT EQUAL TO 1
!
20 SMAX = CABS1(CX(1))
do 30 I = 2,N
   IF(CABS1(CX(I)).LE.SMAX) GO TO 30
   ICAMAX = I
   SMAX = CABS1(CX(I))
30 CONTINUE
RETURN
END FUNCTION ICAMAX

SUBROUTINE MCVFS(A,KA,N,B)
IMPLICIT NONE
INTEGER KA, N
INTEGER I, J, L
REAL A(KA,N),B(*)
!
L = 0
DO J = 1,N
   do 10 I = 1,J
   L = L + 1
10 B(L) = A(I,J)
END DO
RETURN
END SUBROUTINE MCVFS

SUBROUTINE DMCVFS(A,KA,N,B)
IMPLICIT NONE
INTEGER KA, N
INTEGER I, J, L
DOUBLE PRECISION A(KA,N),B(*)
!
L = 0
DO J = 1,N
   do 10 I = 1,J
   L = L + 1
10 B(L) = A(I,J)
END DO
RETURN
END SUBROUTINE DMCVFS

SUBROUTINE MCVSF(A,KA,N,B)
IMPLICIT NONE
INTEGER KA, N
INTEGER I, II, IM1, J, JJ, L
REAL A(KA,N),B(*)
!
A(1,1) = B(1)
IF (N .LT. 2) RETURN
L = (N*(N + 1))/2
!
J = N
do 11 JJ = 2,N
I = J
   do 10 II = 1,J
   A(I,J) = B(L)
   I = I - 1
10 L = L - 1
11 J = J - 1
!
DO I = 2,N
IM1 = I - 1
   do 20 J = 1,IM1
20 A(I,J) = A(J,I)
END DO
RETURN
END SUBROUTINE MCVSF

SUBROUTINE DMCVSF(A,KA,N,B)
IMPLICIT NONE
INTEGER KA, N
INTEGER I, II, IM1, J, JJ, L
DOUBLE PRECISION A(KA,N),B(*)
!
A(1,1) = B(1)
IF (N .LT. 2) RETURN
L = (N*(N + 1))/2
!
J = N
do 11 JJ = 2,N
I = J
   do 10 II = 1,J
   A(I,J) = B(L)
   I = I - 1
10 L = L - 1
11 J = J - 1
!
DO I = 2,N
IM1 = I - 1
   do 20 J = 1,IM1
20 A(I,J) = A(J,I)
END DO
RETURN
END SUBROUTINE DMCVSF

SUBROUTINE MCVRD(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER KA, KB, M, N
INTEGER I, J
REAL A(KA,N)
DOUBLE PRECISION B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = A(I,J)
END DO
RETURN
END SUBROUTINE MCVRD

SUBROUTINE MCVDR(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER KA, KB, M, N
INTEGER I, J
DOUBLE PRECISION A(KA,N)
REAL B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
10 B(I,J) = A(I,J)
END DO
RETURN
END SUBROUTINE MCVDR

SUBROUTINE MCVRC(M,N,A,KA,B,KB)
IMPLICIT NONE
INTEGER KA, KB, M, N
INTEGER I, J
REAL A(KA,N)
COMPLEX B(KB,N)
!
DO J = 1,N
   do 10 I = 1,M
